#!/usr/bin/env bash
# ===========================================
# uninstall.sh — Remove links and generated files created by install.sh
# ===========================================
# Removes every symlink that points into this repo and every file install.sh
# generated (recognised by its "generated" marker), and offers to restore the
# newest .bak.<timestamp> backup of each. Keeps installed packages, Oh My Zsh,
# TPM, Claude account dirs, and ~/.config/dotfiles (config, secrets, local
# extensions, backups).
#
# Usage:
#   ./uninstall.sh            Remove after one confirmation
#   ./uninstall.sh --dry-run  Show what would be removed
#   ./uninstall.sh --yes      Remove and restore backups without prompting

set -euo pipefail

DOTFILES_DIR="$(cd "$(dirname "$0")" && pwd)"

DRY_RUN=false
ASSUME_YES=false
for arg in "$@"; do
  case "$arg" in
    --dry-run|--test) DRY_RUN=true ;;
    -y|--yes) ASSUME_YES=true ;;
    -h|--help)
      cat <<'HELP'
Usage: ./uninstall.sh [--dry-run] [--yes]

Remove the symlinks and generated files created by install.sh, and offer to
restore the backups install.sh made of the files it replaced.

  --dry-run  Show what would be removed; change nothing
  -y, --yes  Do not prompt (also restores backups)
  -h, --help Show this help

Kept: installed packages, Oh My Zsh, TPM, Claude account dirs, and
~/.config/dotfiles (config.sh, .secrets, local extensions, backups).
HELP
      exit 0
      ;;
    *) echo "Unknown option: $arg (see --help)" >&2; exit 1 ;;
  esac
done

# ------------------------------------
# Helpers
# ------------------------------------

info()    { printf "  \033[1;34m%-50s\033[0m %s\n" "$1" "$2"; }
success() { printf "  \033[1;32m%-50s\033[0m %s\n" "$1" "$2"; }

confirm() {
  [ "$ASSUME_YES" = true ] && return 0
  local answer
  printf "  %s [y/N] " "$1"
  read -r answer
  [[ "$answer" =~ ^[Yy]$ ]]
}

# remove_path <path> — delete a link, file or dir (or report it in dry-run)
remove_path() {
  if [ "$DRY_RUN" = true ]; then
    info "$1" "would remove"
  else
    rm -rf "$1"
    success "$1" "removed"
  fi
}

# restore_backup <path> — offer the newest <path>.bak.<timestamp> install.sh made
restore_backup() {
  local backup
  backup="$(ls -1d "$1".bak.* 2>/dev/null | sort | tail -n 1 || true)"
  [ -n "$backup" ] || return 0
  if [ "$DRY_RUN" = true ]; then
    info "$1" "would offer to restore ${backup##*/}"
  elif confirm "Restore $1 from ${backup##*/}?"; then
    mv "$backup" "$1"
    success "$1" "restored"
  fi
  return 0
}

# is_generated <file> — true when install.sh wrote the file
is_generated() {
  grep -qE "^# (Generated by dotfiles|Auto-generated by install\.sh)" "$1" 2>/dev/null
}

# ------------------------------------
# Confirm
# ------------------------------------

if [ "$DRY_RUN" = true ]; then
  info "Mode" "DRY RUN — nothing is changed"
elif ! confirm "Remove dotfiles links and generated files from $HOME?"; then
  exit 0
fi

# ------------------------------------
# Symlinks into the repo
# ------------------------------------

echo ""
echo "Removing links into $DOTFILES_DIR..."
echo ""

links="$(
  {
    find "$HOME" -maxdepth 1 -type l
    [ -d "$HOME/.config" ] && find "$HOME/.config" -maxdepth 3 -type l
    [ -d "$HOME/bin" ] && find "$HOME/bin" -maxdepth 1 -type l
  } 2>/dev/null | while IFS= read -r link; do
    if [[ "$(readlink "$link")" == "$DOTFILES_DIR"/* ]]; then
      printf '%s\n' "$link"
    fi
  done
)"
if [ -z "$links" ]; then
  info "No links into the repo" ""
else
  while IFS= read -r link; do
    remove_path "$link"
    restore_backup "$link"
  done <<< "$links"
fi

# ------------------------------------
# Generated files
# ------------------------------------

echo ""
echo "Removing generated files..."
echo ""

for file in "$HOME/.gitconfig" "$HOME"/.gitconfig-* "$HOME/.aerospace.toml" "$HOME/.aliases.d"/*.sh; do
  [ -f "$file" ] && [ ! -L "$file" ] && is_generated "$file" || continue
  remove_path "$file"
  restore_backup "$file"
done

# Drop ~/.aliases.d only when nothing but generated files lived there
if [ -d "$HOME/.aliases.d" ] && [ -z "$(ls -A "$HOME/.aliases.d")" ] && [ "$DRY_RUN" = false ]; then
  rmdir "$HOME/.aliases.d"
  success "$HOME/.aliases.d" "removed (empty)"
fi

state_dir="${XDG_STATE_HOME:-$HOME/.local/state}/dotfiles"
[ -d "$state_dir" ] && remove_path "$state_dir"

# Claude status line entries that point at this repo's script
# shellcheck source=lib/dotfiles.sh
source "$DOTFILES_DIR/lib/dotfiles.sh"
load_config
statusline_cmd="$DOTFILES_DIR/tools/claude-statusline.sh"
if command -v jq > /dev/null 2>&1; then
  for i in $(seq 1 99); do
    [ -z "$(claude_account "$i" NAME)" ] && break
    settings="$(claude_config_dir "$i")/settings.json"
    jq -e --arg cmd "$statusline_cmd" '.statusLine.command == $cmd' "$settings" > /dev/null 2>&1 || continue
    if [ "$DRY_RUN" = true ]; then
      info "$settings" "would remove statusLine"
    else
      tmp="$(mktemp)"
      jq 'del(.statusLine)' "$settings" > "$tmp" && cat "$tmp" > "$settings"
      rm -f "$tmp"
      success "$settings" "statusLine removed"
    fi
  done
fi

# ------------------------------------
# Keyboard layout copy (macOS)
# ------------------------------------

kbd_dst="$HOME/Library/Keyboard Layouts/UA-RU-layout.bundle"
if [ "$(uname -s)" = "Darwin" ] && [ -d "$kbd_dst" ] &&
   diff -rq "$DOTFILES_DIR/keyboards/UA-RU-layout.bundle" "$kbd_dst" > /dev/null 2>&1; then
  if [ "$DRY_RUN" = true ] || confirm "Remove the UA-RU keyboard layout (log out afterwards)?"; then
    remove_path "$kbd_dst"
  fi
fi

# ------------------------------------
# Done
# ------------------------------------

echo ""
echo "Kept: installed packages, ~/.oh-my-zsh, ~/.tmux/plugins, Claude account dirs,"
echo "      and ${XDG_CONFIG_HOME:-$HOME/.config}/dotfiles (config, secrets, local extensions, backups)."
echo "Remove them manually if no longer needed. Restart your shell."
